Here is the commit message:
drm/msm: Fix dirtyfb refcounting

refcount_t complains about 0->1 transitions, which isn't *quite* what we
wanted.  So use dirtyfb==1 to mean that the fb is not connected to any
output that requires dirtyfb flushing, so that we can keep the underflow
and overflow checking.

Fixes: 9e4dde28e9cd ("drm/msm: Avoid dirtyfb stalls on video mode displays (v2)")
Signed-off-by: Rob Clark <robdclark@chromium.org>
Link: https://lore.kernel.org/r/20220304202146.845566-1-robdclark@gmail.com

Here is the root cause:
The bug was caused by improper reference counting for the `dirtyfb` variable, where a transition from 0 to 1 was not handled correctly. This led to situations where the framebuffer could be incorrectly identified as needing dirty flushing when it should not, resulting in stalls on video mode displays. The logic needed to be adjusted to treat a reference count of 1 as an indication that the framebuffer is not connected to any output requiring dirty flushing.

Here is the patch:

 static int msm_framebuffer_dirtyfb(struct drm_framebuffer *fb,
 				   struct drm_file *file_priv, unsigned int flags,
 				   unsigned int color, struct drm_clip_rect *clips,
 				   unsigned int num_clips)
 {
 	struct msm_framebuffer *msm_fb = to_msm_framebuffer(fb);

 	/* If this fb is not used on any display requiring pixel data to be
 	 * flushed, then skip dirtyfb
 	 */
-	if (refcount_read(&msm_fb->dirtyfb) == 0)
+	if (refcount_read(&msm_fb->dirtyfb) == 1)
 		return 0;

 	return drm_atomic_helper_dirtyfb(fb, file_priv, flags, color,
 					 clips, num_clips);
 }


 static struct drm_framebuffer *msm_framebuffer_init(struct drm_device *dev,
 		const struct drm_mode_fb_cmd2 *mode_cmd, struct drm_gem_object **bos)
 {
 	const struct drm_format_info *info = drm_get_format_info(dev,
 								 mode_cmd);
 	struct msm_drm_private *priv = dev->dev_private;
 	struct msm_kms *kms = priv->kms;
 	struct msm_framebuffer *msm_fb = NULL;
 	struct drm_framebuffer *fb;
 	const struct msm_format *format;
 	int ret, i, n;

 	drm_dbg_state(dev, "create framebuffer: mode_cmd=%p (%dx%d@%4.4s)",
 			mode_cmd, mode_cmd->width, mode_cmd->height,
 			(char *)&mode_cmd->pixel_format);

 	n = info->num_planes;
 	format = kms->funcs->get_format(kms, mode_cmd->pixel_format,
 			mode_cmd->modifier[0]);
 	if (!format) {
 		DRM_DEV_ERROR(dev->dev, "unsupported pixel format: %4.4s\n",
 				(char *)&mode_cmd->pixel_format);
 		ret = -EINVAL;
 		goto fail;
 	}

 	msm_fb = kzalloc(sizeof(*msm_fb), GFP_KERNEL);
 	if (!msm_fb) {
 		ret = -ENOMEM;
 		goto fail;
 	}

 	fb = &msm_fb->base;

 	msm_fb->format = format;

 	if (n > ARRAY_SIZE(fb->obj)) {
 		ret = -EINVAL;
 		goto fail;
 	}

 	for (i = 0; i < n; i++) {
 		unsigned int width = mode_cmd->width / (i ? info->hsub : 1);
 		unsigned int height = mode_cmd->height / (i ? info->vsub : 1);
 		unsigned int min_size;

 		min_size = (height - 1) * mode_cmd->pitches[i]
 			 + width * info->cpp[i]
 			 + mode_cmd->offsets[i];

 		if (bos[i]->size < min_size) {
 			ret = -EINVAL;
 			goto fail;
 		}

 		msm_fb->base.obj[i] = bos[i];
 	}

 	drm_helper_mode_fill_fb_struct(dev, fb, mode_cmd);

 	ret = drm_framebuffer_init(dev, fb, &msm_framebuffer_funcs);
 	if (ret) {
 		DRM_DEV_ERROR(dev->dev, "framebuffer init failed: %d\n", ret);
 		goto fail;
 	}

+	refcount_set(&msm_fb->dirtyfb, 1);
+
 	drm_dbg_state(dev, "create: FB ID: %d (%p)", fb->base.id, fb);

 	return fb;

 fail:
 	kfree(msm_fb);

 	return ERR_PTR(ret);
 }



